if conocidas:
    try:
        for palabra in texto_encargo.replace(",", " ").replace(";", " ").split():
            # una palabra con comillas es una etiqueta o texto pegado como
            # material, no una funcion que se vaya a tocar: no cuenta.
            if '"' in palabra or "'" in palabra or '`' in palabra:
                continue
            limpia = palabra.strip("()[]{}<>\"'`.:")
            if limpia in conocidas and limpia not in funciones:
                funciones.append(limpia)
    except Exception:
        pass
return funciones

propuesta.texto_nuevo:
if conocidas:
    try:
        # Se necesita el contexto para saber si una palabra conocida es una funcion.
        # Se busca si la palabra conocida viene precedida por 'def ' o 'funcion '.
        # Si no, se considera un dato o parametro y no se agrega a la lista de funciones.
        palabras_con_contexto = texto_encargo.split()
        for i, palabra in enumerate(palabras_con_contexto):
            limpia = palabra.strip("()[]{}<>\"'`.:")
            if limpia in conocidas and limpia not in funciones:
                # Comprobar si la palabra conocida viene despues de 'def' o 'funcion'
                if i > 0:
                    anterior = palabras_con_contexto[i-1].strip()
                    if anterior == 'def' or anterior == 'funcion':
                        funciones.append(limpia)
                # Las palabras que empiezan por raya baja siempre cuentan
                elif limpia.startswith("_"):
                    funciones.append(limpia)
    except Exception:
        pass
return funciones

